function minIncrementForUnique(nums) {
  // Counting: walk every value from 0 upward and push surplus copies one step higher.
  const count = new Map();
  let max = 0;
  for (const v of nums) {
    count.set(v, (count.get(v) || 0) + 1);
    max = Math.max(max, v);
  }
  let moves = 0, carry = 0;
  for (let v = 0; v <= max + nums.length; v++) {
    const here = (count.get(v) || 0) + carry;
    carry = Math.max(0, here - 1);
    moves += carry;
  }
  return moves;
}

